INSERT INTO public.annotation_results VALUES (108, 'test_4', 107, 'Welstandsystemen bebouwing', 'Wealth systems building', 'https://maps.amsterdam.nl/open_geodata/?k=174', 'https://maps.amsterdam.nl/welstand', 'WELSTAND_SYSTEMEN', 'VectorTessellation', 'CoverageDS', 'VectorTessellation', 'CoverageDS', 0.92, 'Polygons form an area-wide partition of Amsterdam building typology systems, so this is a tessellation. The thematic classes (Systeemnaam) indicate full-area categorical coverage rather than discrete objects or patches.', NULL, '2026-05-11 22:02:14.50484+02');
