INSERT INTO public.annotation_results VALUES (235, 'V1_test_2_gemini', 6, 'Wilde bijen', 'Wild bees', 'https://maps.amsterdam.nl/open_geodata/?k=135', 'https://maps.amsterdam.nl/bijen', 'BIJEN', 'PointDS', 'AmountDS', 'PointDS', 'EventDS', 0.9, 'The dataset represents observations of wild bees at specific locations and times, which constitutes an event-based phenomenon recorded at discrete points.', NULL, '2026-05-12 12:52:46.620944+02');
