INSERT INTO public.annotation_results VALUES (308, 'V1_test_2_gemini', 79, 'Rainproof - Polderriool', 'Rainproof - Polder sewerage', 'https://maps.amsterdam.nl/open_geodata/?k=291', 'https://maps.amsterdam.nl/rainproof', 'RAINPROOF_POLDERRIOOL', 'PlainVectorRegion', 'PatchDS', 'PlainVectorRegion', 'ObjectDS', 0.9, 'The layer represents discrete areas of polder sewerage projects (''Rainproof'' infrastructure). These are bounded real-world facilities/managed assets represented as polygons, fitting the definition of ObjectDS. They do not form a complete coverage or tessellation of the city.', NULL, '2026-05-12 12:52:46.620944+02');
