INSERT INTO public.annotation_results VALUES (330, 'V1_test_2_gemini', 101, 'Verkeersinformatiesystemen - BFA', 'Traffic Information Systems - BFA', 'https://maps.amsterdam.nl/open_geodata/?k=266', 'https://maps.amsterdam.nl/vis', 'VIS_BFA', 'PointDS', 'ObjectDS', 'PointDS', 'ObjectDS', 1, 'The dataset represents specific traffic control installations (e.g., bollards, barriers) as point locations. Each point is a distinct real-world facility or asset, making ObjectDS the most appropriate entity type.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (331, 'V1_test_2_gemini', 102, 'Broedende vogels', 'Breeding birds', 'https://maps.amsterdam.nl/open_geodata/?k=87', 'https://maps.amsterdam.nl/vogels', 'VOGELS', 'PointDS', 'ObjectDS', 'PointDS', 'ObjectDS', 0.9, 'The dataset represents specific locations (points) where breeding birds have been recorded. While there are numeric fields indicating counts, the points represent the nesting locations (objects/facilities) rather than the counts themselves being the primary phenomenon. Therefore, it is classified as an ObjectDS.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (332, 'V1_test_2_gemini', 103, 'Vondelpark zitbanken', 'Vondelpark benches', 'https://maps.amsterdam.nl/open_geodata/?k=248', 'https://maps.amsterdam.nl/vondelpark_zitbanken', 'VONDELPARK_ZITBANKEN', 'PointDS', 'ObjectDS', 'PointDS', 'ObjectDS', 1, 'The dataset represents a collection of individual park benches, which are discrete, identifiable, real-world assets. The points are mapped to show the location of these assets, confirming an ObjectDS classification.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (333, 'V1_test_2_gemini', 104, 'Walkability', 'Walkability', 'https://maps.amsterdam.nl/open_geodata/?k=298', 'https://maps.amsterdam.nl/walkability', 'WALKABILITY', 'LineDS', 'NetworkDS;ObjectDS', 'LineDS', 'NetworkDS', 0.9, 'The dataset represents a network of street segments (indicated by ''Straatvaknummer'') where walkability and congestion are attributes, qualifying it as a NetworkDS.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (334, 'V1_test_2_gemini', 105, 'Wandkunst', 'Wall art', 'https://maps.amsterdam.nl/open_geodata/?k=272', 'https://maps.amsterdam.nl/wandkunst', 'WANDKUNST', 'PointDS', 'ObjectDS', 'PointDS', 'ObjectDS', 1, 'The dataset contains point locations representing distinct, identifiable real-world objects (wall art/sculptures) with descriptive attributes. The geometry type is PointDS, and the primary entity type is ObjectDS.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (335, 'V1_test_2_gemini', 106, 'Welstandniveaus bebouwing', 'Wealth levels building', 'https://maps.amsterdam.nl/open_geodata/?k=173', 'https://maps.amsterdam.nl/welstand', 'WELSTAND_NIVEAUS', 'VectorTessellation', 'CoverageDS', 'PlainVectorRegion', 'CoverageDS', 0.9, 'The dataset represents a thematic classification of Amsterdam''s building areas based on ''Welstandniveaus'' (aesthetic/wealth levels). As these polygons represent specific land-use or zoning-like functional categories for aesthetic regulation, it is classified as a CoverageDS.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (336, 'V1_test_2_gemini', 107, 'Welstandsystemen bebouwing', 'Wealth systems building', 'https://maps.amsterdam.nl/open_geodata/?k=174', 'https://maps.amsterdam.nl/welstand', 'WELSTAND_SYSTEMEN', 'VectorTessellation', 'CoverageDS', 'VectorTessellation', 'CoverageDS', 0.95, 'The dataset partitions the city of Amsterdam into homogeneous zones based on urban development and architectural styles (welstand systems), which constitutes an exhaustive thematic coverage of the city''s built environment.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (337, 'V1_test_2_gemini', 108, 'Amsterdam onder vuur in WOII', 'Amsterdam under attack in WWII', 'https://maps.amsterdam.nl/open_geodata/?k=100', 'https://maps.amsterdam.nl/woii', 'WOII', 'PointDS', 'EventDS', 'PointDS', 'EventDS', 1, 'The dataset represents specific historical war-related incidents (bombs, crashes) occurring at distinct point locations over time during WWII, making it an event-based dataset.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (338, 'V1_test_2_gemini', 109, 'Woningbouwplannen', 'Housing plans', 'https://maps.amsterdam.nl/open_geodata/?k=142', 'https://maps.amsterdam.nl/woningbouwplannen', 'WONINGBOUWPLANNEN', 'PlainVectorRegion', 'ObjectDS', 'PlainVectorRegion', 'ObjectDS', 0.9, 'The layer represents housing project polygons. These are identifiable real-world development sites/objects. Although they contain many numeric attributes (housing counts, dates), these are attributes of the project objects rather than the primary mapped phenomenon being an amount.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (339, 'V1_test_2_gemini', 110, 'Zelfbouwkavels', 'Do-it-yourself plots', 'https://maps.amsterdam.nl/open_geodata/?k=60', 'https://maps.amsterdam.nl/zelfbouwkavels', 'ZELFBOUWKAVELS', 'PointDS', 'ObjectDS', 'PointDS', 'ObjectDS', 1, 'The dataset represents individual do-it-yourself housing plots as point locations, which are discrete real-world objects/projects. The numeric attributes like ''Aantal_woningen'' do not turn these points into an AmountDS.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (340, 'V1_test_2_gemini', 111, 'Zonnepanelen op erfgoed', 'Solar panels on heritage', 'https://maps.amsterdam.nl/open_geodata/?k=320', 'https://maps.amsterdam.nl/zonnedaken_erfgoed', 'ZONNEDAKEN_ERFGOED', 'PlainVectorRegion', 'ObjectDS', 'PlainVectorRegion', 'CoverageDS', 0.9, 'The layer represents an exhaustive thematic classification of heritage sites concerning solar panel installation suitability, covering the study area in functional categories. Therefore, it is classified as a full-area thematic coverage.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (341, 'V1_test_2_gemini', 112, 'Zonnepanelen', 'Solar panels', 'https://maps.amsterdam.nl/open_geodata/?k=251', 'https://maps.amsterdam.nl/zonnepanelen', 'ZONNEPANELEN2017', 'PointDS', 'AmountDS', 'PointDS', 'ObjectDS', 0.95, 'The dataset maps individual solar panel installations as points. These are discrete, countable real-world assets, even though they contain numeric attributes like panel count and power output; therefore, ObjectDS is preferred over AmountDS.', NULL, '2026-05-12 12:52:46.620944+02');
INSERT INTO public.annotation_results VALUES (342, 'V1_test_2_gemini', 113, 'Zwemwater', 'Swimming water', 'https://maps.amsterdam.nl/open_geodata/?k=218', 'https://maps.amsterdam.nl/zwemwater', 'ZWEMWATER', 'PointDS', 'ObjectDS', 'PointDS', 'ObjectDS', 1, 'The dataset maps specific swimming water locations (facilities) as points, which are distinct, identifiable real-world objects.', NULL, '2026-05-12 12:52:46.620944+02');
